macro_rules! apply_match {
    () => {
        # [doc = " Presumes that there is at least match_len bytes in output left."] # [inline] fn apply_match (out_slice : & mut [u8] , out_pos : usize , dist : usize , match_len : usize , out_buf_size_mask : usize ,) { debug_assert ! (out_pos . checked_add (match_len) . unwrap () <= out_slice . len ()) ; let source_pos = out_pos . wrapping_sub (dist) & out_buf_size_mask ; if match_len == 3 { let out_slice = Cell :: from_mut (out_slice) . as_slice_of_cells () ; if let Some (dst) = out_slice . get (out_pos .. out_pos + 3) { let src = out_slice . get (source_pos) . zip (out_slice . get ((source_pos + 1) & out_buf_size_mask)) . zip (out_slice . get ((source_pos + 2) & out_buf_size_mask)) ; if let Some (((a , b) , c)) = src { dst [0] . set (a . get ()) ; dst [1] . set (b . get ()) ; dst [2] . set (c . get ()) ; } } return ; } if cfg ! (not (any (target_arch = "x86" , target_arch = "x86_64"))) { transfer (out_slice , source_pos , out_pos , match_len , out_buf_size_mask) ; return ; } if source_pos >= out_pos && (source_pos - out_pos) < match_len { transfer (out_slice , source_pos , out_pos , match_len , out_buf_size_mask) ; } else if match_len <= dist && source_pos + match_len < out_slice . len () { if source_pos < out_pos { let (from_slice , to_slice) = out_slice . split_at_mut (out_pos) ; to_slice [.. match_len] . copy_from_slice (& from_slice [source_pos .. source_pos + match_len]) ; } else { let (to_slice , from_slice) = out_slice . split_at_mut (source_pos) ; to_slice [out_pos .. out_pos + match_len] . copy_from_slice (& from_slice [.. match_len]) ; } } else { transfer (out_slice , source_pos , out_pos , match_len , out_buf_size_mask) ; } }
    };
}

apply_match!()